  "This conversation is running on another computer (one of yours). Take it over here, or let Liaison answer it.":
    "Cette discussion tourne sur un autre ordinateur (l'un des vôtres). Reprenez-la ici, ou laissez Liaison y répondre.",
  "This conversation is running on another computer ({{name}}'s). Take it over here, or let Liaison answer it.":
    "Cette discussion tourne sur un autre ordinateur (celui de {{name}}). Reprenez-la ici, ou laissez Liaison y répondre.",
