  "Approve this device in your browser so the conversation can run on this machine. Your message is sent as soon as it is approved.":
    "Approuvez cet appareil dans votre navigateur pour que la discussion s'exécute sur cet ordinateur. Votre message part dès l'approbation.",
  "Waiting for approval": "En attente d'approbation",
  "Approval status unknown, reconnecting": "Approbation pas encore confirmée, reconnexion en cours",
