  "A pending customer reply can be approved, edited or rejected from its Home card, without opening the ticket thread. Off: Home only opens the ticket.":
    "Une réponse client en attente peut être approuvée, modifiée ou refusée depuis sa carte d'accueil, sans ouvrir le fil du ticket. Désactivé : l'accueil ouvre seulement le ticket.",
  "Ticket id prefix": "Préfixe des identifiants",
