    "Préfixez les identifiants des tickets par un code court selon un champ, par exemple ticket-B2B-123. Le code suit la valeur actuelle du ticket ; le numéro ne change jamais, et toutes les formes d'un identifiant restent valables, y compris dans les mails.",
