  "kernel.agentSafety.desc":
    "Comment l'agent se comporte après avoir lu du texte venu de l'extérieur de l'organisation, comme un mail entrant, une page web ou le résultat d'un outil connecté. Ce texte peut contenir des instructions écrites par un inconnu.",
