  "mail.encryption.privateHelp":
    "Vous seul pouvez la lire, sur les appareils où vous la déverrouillez avec votre mot de passe de boîte mail ou une clé d'accès. Le serveur ne peut pas la lire : votre agent la lit seulement quand votre boîte est déverrouillée dans une fenêtre Liaison ouverte. Par sécurité, les routines et les agents ne peuvent pas lire le courrier privé quand vous n'êtes pas connecté : ces exécutions vous attendent (Exécuter maintenant).",
  "mail.encryption.transparentHelp":
    "Chiffrée au repos. Vous et votre agent la lisez, y compris dans les routines, sans mot de passe de boîte mail. Les administrateurs de votre organisation ne peuvent pas la lire. Celui qui exploite ce serveur Liaison détient la clé. Une boîte standard (transparente) est lue côté serveur et les routines tournent sans vous.",
