  "tickets.closeSilent.help":
    "Quand un ticket attend le client et que notre message est le dernier, envoyer la relance ci-dessous après quelques jours, puis clôturer le ticket s'il ne répond toujours pas. Chaque étape passe par les approbations comme tout autre envoi, au nom de la routine Close silent tickets, jamais au vôtre. Seuls comptent les tickets auxquels nous écrivons après l'activation.",
